# region: shape
def shape(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: sift
def sift(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: fold
def fold(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(emit(sift(shape(raw))))

